  makeWall(side, min, max){

    this.wall = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Sprite(this.e.ui.red);
    this.wall.anchor.x = 0.5;
    this.wall.anchor.y = 1;
    this.wall.width=200;
    this.wall.height=this.e.u.ran(max-min)+min;

    if( this.wall.height + this.wallHeight > this.gameHeight ){

      this.wall.height = this.gameHeight - this.wallHeight+10;

    }

    // wall pos

    if(side==="l"){
      this.wall.position.x = -400;
    }else{
      this.wall.position.x = 400;
    }

    // randomize color

    var ranCol = this.e.u.ran(2);
    if(ranCol===0){
      this.wall.col="b";
    }else{
      this.wall.col="r";
    }

    // if at start set color manually

    if(this.wallHeight<2000 && side==="l"){
      this.wall.col="b";
    }

    if(this.wallHeight<2000 && side==="r"){
      this.wall.col="r";
    }

    // set color

    if(this.wall.col==="b"){
      this.wall.texture=this.e.ui.cyan;
    }else{
      this.wall.texture=this.e.ui.red;
    }

    // set posiition
    
    this.wall.position.y = -this.wallHeight;

    // add to scene

    this.wall._zIndex=1;
    this.levCont.addChild(this.wall);
    this.plats.push(this.wall);

    // tick height

    this.wallHeight+=this.wall.height-8;

    //-------------------------------------

    // create graphic container

    this.wallCont = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Container();
    this.wallCont.sortableChildren = true;
    this.levCont.addChild(this.wallCont);

    if(this.wall.col==="b"){
      this.wallTop = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Sprite(this.e.ui.topBlueEmpty);
      this.wallMid = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Sprite(this.e.ui.midBlueEmpty);
      this.wallBot = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Sprite(this.e.ui.botBlueEmpty);
      this.wallIcon = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Sprite(this.e.ui.iconBlueEmpty);
    }else{
      this.wallTop = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Sprite(this.e.ui.topRedEmpty);
      this.wallMid = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Sprite(this.e.ui.midRedEmpty);
      this.wallBot = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Sprite(this.e.ui.botRedEmpty);
      this.wallIcon = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Sprite(this.e.ui.iconRedEmpty);
    }
    
    this.wallTop.anchor.x = 0.5;
    this.wallTop.anchor.y = 0;
    this.wallTop._zIndex = 1900
    this.wallCont.addChild(this.wallTop);

    this.wallMid.anchor.x = 0.5;
    this.wallMid.anchor.y = 0;
    this.wallMid.height = this.wall.height-40;
    this.wallMid.position.y = 20;
    this.wallMid._zIndex = 1900
    this.wallCont.addChild(this.wallMid);

    this.wallBot.anchor.x = 0.5;
    this.wallBot.anchor.y = 1;
    this.wallBot.position.y = this.wall.height;
    this.wallBot._zIndex = 1900
    this.wallCont.addChild(this.wallBot);

    this.wallIcon.anchor.x = 0.5;
    this.wallIcon.anchor.y = 0.5;
    this.wallIcon.position.y = this.wall.height/2;
    this.wallIcon._zIndex = 1901
    this.wallCont.addChild(this.wallIcon);

    this.wall.cont = this.wallCont;
    this.wall.wallTop = this.wallTop;
    this.wall.wallMid = this.wallMid;
    this.wall.wallBot = this.wallBot;
    this.wall.wallIcon = this.wallIcon;

    this.wall.filled=false;

    this.wallCont.bkg = this.wall;

    var wallDelay = this.e.u.ran(10)/10;
    gsap__WEBPACK_IMPORTED_MODULE_2__.gsap.to(  this.wallCont, {alpha: .4, duration: 1, delay: wallDelay, yoyo: true, repeat:-1, ease: "linear"});

  }

  fillWall(wall){

    if(wall.filled===false){

      this.e.s.p("push");

      wall.filled=true;
        
      if(wall.col==="b"){
        wall.wallTop.texture = this.e.ui.topBlueFull
        wall.wallMid.texture = this.e.ui.midBlueFull
        wall.wallBot.texture = this.e.ui.botBlueFull
        
      }else{
        wall.wallTop.texture = this.e.ui.topRedFull
        wall.wallMid.texture = this.e.ui.midRedFull
        wall.wallBot.texture = this.e.ui.botRedFull
        
      }

      if(wall.position.x===400){
        wall.position.x=425;
        this.setScoreText(this.pushPoints, wall.position.x-140, wall.position.y-wall.height/2, 20, "push");
      }

      if(wall.position.x===-400){
        wall.position.x=-425;
        this.setScoreText(this.pushPoints, wall.position.x+140, wall.position.y-wall.height/2, 20, "push");
      }

    }

  }

  wallControl(){

    for(var i=0; i<this.plats.length; i++){

      this.plats[i].cont.position.x = this.plats[i].position.x;
      this.plats[i].cont.position.y = this.plats[i].position.y - this.plats[i].height;
      this.plats[i].alpha = 0;

      if(this.plats[i].col===this.playerColor){

        if(this.plats[i].col==="b"){
          this.plats[i].wallIcon.texture = this.e.ui.iconBlueFull
        }else if(this.plats[i].col==="r"){
          this.plats[i].wallIcon.texture = this.e.ui.iconRedFull
        }

      }else{

        if(this.plats[i].col==="b"){
          this.plats[i].wallIcon.texture = this.e.ui.iconBlueEmpty
        }else if(this.plats[i].col==="r"){
          this.plats[i].wallIcon.texture = this.e.ui.iconRedEmpty
        }
        
      }

    }

  }

