  setParticle(x, y){

    for(var i=0; i<this.allParticles.length; i++){

        if(this.allParticles[i].action==="ready"){

          // console.log("make part")

          if(this.curColor==="r"){
            this.allParticles[i].texture = this.e.ui.cyan;
          }else{
            this.allParticles[i].texture = this.e.ui.red;
          }

          this.allParticles[i].position.x = x;
          this.allParticles[i].position.y = y;
          this.allParticles[i].width = this.e.u.ran(18)+3;
          this.allParticles[i].height = this.e.u.ran(18)+3;

          this.allParticles[i].xspeed=this.e.u.nran(30);
          this.allParticles[i].yspeed = this.e.u.nran(50);

          gsap__WEBPACK_IMPORTED_MODULE_2__.gsap.to( this.allParticles[i], {width: 0.1, height: 0.1, duration: 1, delay: 1, ease: "linear"});

          this.allParticles[i].action="go"
          i=10000;

        }
    
    }

  }

  particleControl(){

    if(this.particleControlVars===undefined){

      this.particleCount = 0;
      this.particleLim = 10;

      this.allParticles=[];

      for(var i=0; i<300; i++){

        this.part = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Sprite(this.e.ui.red);
        this.part.anchor.x = 0.5;
        this.part.anchor.y = 0.5;
        this.part.position.x = 10000;
        this.part.action = "ready"
        this.part.count = 0
        this.part._zIndex = 20;
        this.levCont.addChild(this.part);

        this.allParticles.push(this.part);

      }

      this.particleControlVars=true;

    }

    for(var i=0; i<this.allParticles.length; i++){

      var p = this.allParticles[i];

      if(p.action==="ready"){

        p.position.x = 10000;

      }else if(p.action==="go"){

        p.position.x += p.xspeed;
        p.position.y += p.yspeed;
        p.rotation+=p.xspeed*10;
        p.yspeed += this.e.dt*100;


        p.count+=this.e.dt;
        if(p.count>2 ){
            gsap__WEBPACK_IMPORTED_MODULE_2__.gsap.killTweensOf(p.scale);
            p.count=0
            p.action="ready"
        }

      }

    }

  }

  penaltyControl(){

    if(this.penaltyControlVars===undefined){

      this.penaltyCount = 0;
      this.penaltyLim = 10;

      this.allPenalties=[];

      this.penaltyControlVars=true;

    }

    var gamePerc = (this.playerCont.position.y/this.gameHeight)*-1;

    // console.log(gamePerc);

    // ------------------------------------------------------------------------------------

    // make penalties

    if(this.action==="game"){
      
      this.penaltyCount+=this.e.dt;

    }

    if(this.penaltyCount>this.penaltyLim/4){

      this.penaltyCount=0;

      if(this.playerColor==="b"){
        this.pen = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Sprite(this.e.ui.t_penaltyRed);
      }else{
        this.pen = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Sprite(this.e.ui.t_penaltyBlue);
      }
      
      this.pen.anchor.x = 0.5;
      this.pen.anchor.y = 0.5;
      this.pen.rotation =  this.e.u.ca(45);
      this.pen.position.x = this.e.u.nran(300);
      this.pen.position.y = this.playerCont.position.y - 2000;
      this.pen.scale.x = this.pen.scale.y = .7;
      this.pen._zIndex = 20;
      this.levCont.addChild(this.pen);

      this.allPenalties.push(this.pen);

      //
      
      this.penaltyLim = 11 - (gamePerc*10);

    }

    // ------------------------------------------------------------------------------------

    // hit test penalties

    for(var i=0; i<this.allPenalties.length; i++){

      var c = this.allPenalties[i];

      if(this.e.u.hitTest(this.player,this.allPenalties[i])===true && c.alpha===1 && this.action==="game"){

        console.log( "dost "+this.e.u.getDistance( this.playerCont.position.x, this.playerCont.position.y, this.allPenalties[i].position.x, this.allPenalties[i].position.y ) );

        if(this.e.u.getDistance( this.playerCont.position.x, this.playerCont.position.y, this.allPenalties[i].position.x, this.allPenalties[i].position.y )<30){

          this.e.s.p("enemyHit");

          this.hitPenalty();

          // this.hits+=1;
          // this.score-=50;

          this.bonusScore=0;
          this.life-=10*this.penaltyMult;
          if(this.upperRightText) {
            this.upperRightText.innerHTML = "LIFE: " + Math.round(this.life);
            this.upperRightText.style.opacity = "1";
          }

          if(this.bonusMult>1){
            this.e.s.p("powerDown");
          }

          for(var i=0; i<30; i++){
            this.setParticle(c.position.x, c.position.y)
          }

          c.alpha = 0;
          // this.setScoreText(this.coinPoints, c.position.x, c.position.y, 20, "coin");
        }
        
      }

      c.rotation+=this.e.dt*15;

      // if(this.playerColor==="b"){
      //   c.texture=this.e.ui.coinBlue;
      // }else{
      //   c.texture=this.e.ui.coinRed;
      // }

    }

  }

