  makeCoin(){

    for(var i=0; i<this.e.serverData.allCoinPositions.length; i++){

      this.coin = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Sprite(this.e.ui.coinRed);
      this.coin.anchor.x = 0.5;
      this.coin.anchor.y = 0.5;
      this.coin.rotation =  this.e.u.ca(45);
      this.coin.position.x = this.e.serverData.allCoinPositions[i][0];
      this.coin.position.y = this.e.serverData.allCoinPositions[i][1];
      // this.coin.position.x = this.e.u.nran(300);
      // this.coin.position.y = -1000-this.e.u.ran(this.gameHeight-1000);
      this.coin._zIndex = 20;
      this.levCont.addChild(this.coin);
  
      this.allCoins.push(this.coin);

    }

  }

  coinControl(){

    for(var i=0; i<this.allCoins.length; i++){

      var c = this.allCoins[i];

      if(this.e.u.hitTest(this.player,this.allCoins[i])===true && c.alpha===1 && this.action==="game"){

        this.e.s.p("point");

        var pos = [];
        pos.push( this.allCoins[i].position.x );
        pos.push( this.allCoins[i].position.y );

        this.levelCoinHits.push( pos );

        c.alpha = 0;
        this.setScoreText(this.coinPoints, c.position.x, c.position.y, 20, "coin");
        
      }

      c.rotation+=this.e.dt*5;

      if(this.playerColor==="b"){
        c.texture=this.e.ui.coinBlue;
      }else{
        c.texture=this.e.ui.coinRed;
      }

    }

  }

