  bonusShowControl(){

    if(this.bonusShowControlVars===undefined){

      this.bonusShowCount=0;
      this.bonusShowOpacity=0;
      this.bonusShowAction="";
      this.saveBonusLevel=1;
      this.bonusShowControlVars=true;

    }

    if(this.bonusMult!==this.saveBonusLevel){
      this.bonusShowAction="start";
    }

    this.saveBonusLevel=this.bonusMult;

    if(this.bonusShowAction==="start"){

      this.e.s.p("bonus");

      // this.bonusBigText.style.opacity="1";

      // this.bonusBigText.innerHTML = this.bonusText.innerHTML;
      this.bonusShowCount=0;
      this.bonusShowAction="wait";

    }else if(this.bonusShowAction==="wait"){

      if(this.action==="game"){

        this.bonusShowCount+=this.e.dt;
        if(this.bonusShowCount>2){
          this.bonusShowOpacity=1;
          this.bonusShowAction="fade";
          this.bonusShowCount=0;
        }
  
      }

    }else if(this.bonusShowAction==="fade"){

      this.bonusShowOpacity-=this.e.dt;
      if(this.bonusShowOpacity<0){
        this.bonusShowOpacity=0;
        this.bonusShowAction="";
      }

      // this.bonusBigText.style.opacity=this.bonusShowOpacity+"";

    }

  }

  scoreDispControl(){

    if(this.scoreDispControlVars===undefined){

      this.scTextArray=[];

      for(var i=0; i<50; i++){

        this.scText = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Text('0');
        this.scText.anchor.x = .5;
        this.scText._zIndex = 2150;
        this.scText.style = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.TextStyle({
            align: "center",
            lineHeight: 0,
            fill: 0xffffff,
            fontSize: 12,
            fontFamily: "Adam"
        })
        this.scText.resolution = 3;
        this.levCont.addChild(this.scText);

        this.scText.action = "ready"
        this.scText.count = 0

        this.scTextArray.push(this.scText);

      }

      this.scoreDispControlVars=true;

    }

    for(var i=0; i<this.scTextArray.length; i++){

      var s = this.scTextArray[i];

      if(s.action==="ready"){

        s.position.x=10000;
        s.position.y=10;

      }else if(s.action==="left"){

        s.position.y-=this.e.dt*30;
        s.position.x+=this.e.dt*90;
        s.alpha-=this.e.dt*2;

        if(s.alpha<=0){
          s.action="ready";
        }

      }else if(s.action==="right"){

        s.position.y-=this.e.dt*30;
        s.position.x-=this.e.dt*90;
        s.alpha-=this.e.dt*2;

        if(s.alpha<=0){
          s.action="ready";
        }

      }else if(s.action==="up"){

        s.position.y-=this.e.dt*30;
        s.alpha-=this.e.dt*2;

        if(s.alpha<=0){
          s.action="ready";
        }

      }

    }

  }

  setScoreText(num, x, y, size, type){

    // this.score+=num*this.bonusMult;

    if(type==="wrong"){
      this.bonusScore=0;
    }else{
      this.bonusScore+=num*this.bonusMult;
    }
    
    if(type==="right"){
      this.totalRightPoints+=num*this.bonusMult;
      this.levelRightPoints+=num*this.bonusMult;
    }else if(type==="push"){
      this.totalPushPoints+=num*this.bonusMult;
      this.levelPushPoints+=num*this.bonusMult;
    }else if(type==="coin"){
      this.totalCoinPoints+=num*this.bonusMult;
      this.levelCoinPoints+=num*this.bonusMult;
    }else if(type==="wrong"){
      this.totalWrongPoints+=num*this.bonusMult;
      this.levelWrongPoints+=num*this.bonusMult;
    }
    
    for(var i=0; i<this.scTextArray.length; i++){

      if(this.scTextArray[i].action==="ready"){

        this.scTextArray[i].alpha=1;
        this.scTextArray[i].position.x=x;
        this.scTextArray[i].position.y=y;
        this.scTextArray[i].text = (num*this.bonusMult)+""
        this.scTextArray[i].style.fontSize = size*1.5;

        if(type==="push"){

          if(x>0){
            this.scTextArray[i].action="right"
          }else{
            this.scTextArray[i].action="left"
          }
          
        }else{

          this.scTextArray[i].action="up"

        }

        if(this.playerColor==="b"){
          this.scTextArray[i].style.fill = this.blueColor;
        }else{
          this.scTextArray[i].style.fill = this.redColor;
        }

        i=1000;
  
      }

    }
    
    // if(this.life<0){
    //   this.life=0;
    // }

  }

