  switchDirection(dir){

    console.log("switch "+dir)

    this.e.s.p("woosh");
    this.onWall=false;
    this.sideSpeed=0;

    gsap__WEBPACK_IMPORTED_MODULE_2__.gsap.killTweensOf(this.playerChar);

    if(dir==="r"){

      this.dir="l";
      var angleTarg = (Math.round(this.e.u.ca2(this.playerChar.rotation)/90)-1)*-90;

    }else{

      this.dir="r";
      var angleTarg = (Math.round(this.e.u.ca2(this.playerChar.rotation)/90)+1)*90;

    }
     
    gsap__WEBPACK_IMPORTED_MODULE_2__.gsap.to(  this.playerChar, {rotation: this.e.u.ca(angleTarg), duration: .25, ease: "linear"});

  }

  playerControl(){

    this.levelSpeedMult=1.2;

    this.dist = (this.playerCont.position.y/this.gameHeight)*-1;

    if(this.dist<.2){
      this.gameSpeedMultTarget = 1.1;
    }else if(this.dist<.3){
      this.gameSpeedMultTarget = 1.3;
    }else if(this.dist<.4){
      this.gameSpeedMultTarget = 1.4;
    }else if(this.dist<.5){
      this.gameSpeedMultTarget = 1.5;
    }else if(this.dist<.6){
      this.gameSpeedMultTarget = 1.5;
    }else if(this.dist<.7){
      this.gameSpeedMultTarget = 1.6;
    }else if(this.dist<.8){
      this.gameSpeedMultTarget = 1.7;
    }else if(this.dist<.9){
      this.gameSpeedMultTarget = 1.8;
    }else{
      this.gameSpeedMultTarget = 1.8;
    }

    this.gameSpeedMult = this.e.u.lerp(this.gameSpeedMult, this.gameSpeedMultTarget, 1*this.e.dt);
    this.playerCont.position.y-=600*this.e.dt*this.gameSpeedMult*this.levelSpeedMult;
    
    if(this.playerCont.position.y<-this.gameHeight){

      this.action="end start"
      
      console.log("totalCoinPoints: "+this.totalCoinPoints)
      console.log("totalPushPoints: "+this.totalPushPoints)
      console.log("totalRightPoints: "+this.totalRightPoints)
      console.log("totalWrongPoints: "+this.totalWrongPoints)
      console.log("game time: "+this.gameTime)

    }

    // --- CONTROLS -------------------------------------------------------------------------------------------

    if(this.playerControlVars===undefined){

      this.speed=60;
      this.xspeed=0;
      this.yspeed=0;
      this.jumping=true;
      this.jumps=0;
      this.jumpWasLetGo=true;
      this.switchWasLetGo=true;
      this.dir = "l";
      this.playerColor = "b";
      this.sideSpeed = 0;

      this.playerControlVars=true;

    }

    if(this.playerColor==="b"){
      this.playerChar.texture = this.e.ui.playerBlue;
      this.playerGlow.texture = this.e.ui.glowBlue;
    }else{
      this.playerChar.texture = this.e.ui.playerRed;
      this.playerGlow.texture = this.e.ui.glowRed;
    }

    // --- input -------------------------------------------------------------------------------------------

    if(this.rightWasLetGo===undefined){
      this.rightWasLetGo=true;
      this.leftWasLetGo=true;
    }

    // if(this.e.mobile===true){

    //   if(this.e.ui.ongoingTouches.length>0){

    //     if(this.e.ui.ongoingTouches[0].clientX<window.innerWidth/2){



    //     }else{



    //     }

    //   }

    // }

    // ------------------------------------------------------------------------------------------------------

    // press left

    if(this.e.input.keyLeft===true && this.leftWasLetGo===true){

      if(this.dir==="r"){

        this.switchDirection("r");

      }

    }

    if(this.e.input.keyLeft===false){
      this.leftWasLetGo=true;
    }

    // ------------------------------------------------------------------------------------------------------

    // press right

    if(this.e.input.keyRight===true && this.rightWasLetGo===true){

      if(this.dir==="l"){
            
        this.switchDirection("l");

      }

    }

    if(this.e.input.keyRight===false){
      this.rightWasLetGo=true;
    }

    // --- xspeed ----------------------------------------------------------------------------

    this.sideSpeed+=this.e.dt*80;

    if(this.sideSpeed>17){
      this.sideSpeed=17;
    }

    if(this.dir==="l"){

      this.xspeed=-this.sideSpeed*this.gameSpeedMult

    }else if(this.dir==="r"){

      this.xspeed=this.sideSpeed*this.gameSpeedMult

    }

    this.applyX=this.xspeed*this.e.dt*this.speed;

    if(Math.abs(this.applyX>50)){

      console.log(Math.round(this.applyX) + " / " + this.e.dt);

    }

    this.moverx.position.x = this.playerCont.position.x + this.applyX;
    this.moverx.position.y = this.playerCont.position.y;

    this.hitPlat=false;

    for(var i=0; i<this.plats.length; i++){

      if(this.plats[i]!==null){

        if(
          this.playerCont.position.x < this.plats[i].position.x && this.dir==="r" ||
          this.playerCont.position.x > this.plats[i].position.x && this.dir==="l"
          ){
            
          if( this.e.u.checkPlatformX(this.plats[i],this.moverx)===true ){

            // --------------------------------
            // hit wall here
            // --------------------------------

            // this.redFlash.alpha=0;

            if(this.playerColor==="b" && this.plats[i].texture===this.e.ui.cyan){

              this.rightPointCount+=this.e.dt;

              this.fillWall(this.plats[i]);

              this.loopUp();
              this.onWall=true;

            }else if(this.playerColor==="r" && this.plats[i].texture===this.e.ui.red){

              this.rightPointCount+=this.e.dt;

              this.fillWall(this.plats[i]);

              this.loopUp();
              this.onWall=true;

            }else if(this.playerColor==="b" && this.plats[i].texture===this.e.ui.red){

              // this.redFlash.alpha=.2;
              this.wrongPointCount+=this.e.dt;

              this.rightLoop.volume(0)

            }else if(this.playerColor==="r" && this.plats[i].texture===this.e.ui.cyan){

              // this.redFlash.alpha=.2;
              this.wrongPointCount+=this.e.dt;

              this.rightLoop.volume(0)

            }

            this.hitPlat=true;

            // start with zero from where player is
            // add one and check that number until the player hits the ground
            // then set the player to that point

            this.curMoveXPos = this.moverx.position.x;

            for(var j=0; j<800; j++){

              if(this.dir==="l"){
                this.moverx.position.x = this.curMoveXPos+j/10;
              }else{
                this.moverx.position.x = this.curMoveXPos-j/10;
              }

              if( this.e.u.checkPlatformX(this.plats[i],this.moverx)===false ){

                  this.playerCont.position.x=this.moverx.position.x;
                  this.xspeed=0;
                  j=5000;

              }

            }

            this.onGround=true;
            this.xspeed = 0;
            
            i=10000;

          }

        }

      }

    }

    if(this.rightPointCount>.05){

      this.rightPointCount=0;
      
      if(this.dir==="l"){
        this.setScoreText(this.rightPoints, this.playerCont.position.x-12.5, this.playerCont.position.y, 12, "right");
      }else{
        this.setScoreText(this.rightPoints, this.playerCont.position.x+12.5, this.playerCont.position.y, 12, "right");
      }
      
    }

    if(this.wrongPointCount>.05){
      
      this.wrongPointCount=0;
      this.bonusScore=0;

      this.redFlash.alpha=.2;
      this.life-=this.e.dt*50*this.penaltyMult;
      if(this.upperRightText) {
        this.upperRightText.innerHTML = "LIFE: " + Math.round(this.life);
        this.upperRightText.style.opacity = "1";
      }

      for(var i=0; i<2; i++){
        this.setParticle(this.playerCont.position.x, this.playerCont.position.y)
      }

      this.e.s.p("wrong");

      var subtractThisMuch = -this.wrongPoints;

      //dont subtract more than is possible

      if(this.score<this.wrongPoints){
        subtractThisMuch = this.score;
      }

      if(this.dir==="l"){
        this.setScoreText(subtractThisMuch, this.playerCont.position.x-12.5, this.playerCont.position.y, 12, "wrong");
      }else{
        this.setScoreText(subtractThisMuch, this.playerCont.position.x+12.5, this.playerCont.position.y, 12, "wrong");
      }

    }else{

      this.redFlash.alpha=0;

    }

    if(this.hitPlat===false){
      // this.redFlash.alpha=0;
      this.rightLoop.volume(0)

    }

    //it hit nothing, apply the apply X

    if(this.gameSpeedMult<.75){
      this.xspeed=0;
    }else{
      if(this.action==="game"){
        this.makeParticles=true;
      }
      
    }

    this.playerCont.position.x+=this.xspeed*this.e.dt*this.speed;

    if(this.onWallSave!==this.onWall && this.onWall===true){
      this.e.s.p("rightLand");
      // console.log("land right")
    }

    this.onWallSave=this.onWall;

  }

