  enemyControl(){

    if(this.enemyControlVars===undefined){

      // this.enemyCont = new PIXI.Container();
      // this.enemyCont.sortableChildren = true;
      // this.levCont.addChild(this.enemyCont);

      this.enemy = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Sprite(this.e.ui.enemy1);
      this.enemy.position.x = 10000;
      this.enemy.anchor.x = 0.5;
      this.enemy.anchor.y = 0.5;
      this.enemy._zIndex = 1150;
      this.levCont.addChild(this.enemy);

      this.enemy.position.y=-10000;

      this.enemyCount=-10;
      this.enemyLim=30;
      this.enemyBlink=0;
      this.hitBlink=0;
      this.enemyAction="wait"

      this.enemyControlVars=true;

    }

    if(this.action==="center"){

      this.enemyAction="off";
      this.enemy.alpha=0;
      
    }

    if(this.playerColor==="b"){
      this.enemy.texture=this.e.ui.enemy2;
    }else{
      this.enemy.texture=this.e.ui.enemy1;
    }

    if(this.enemyAction==="wait" && this.action==="game"){

      if(this.switchAction==="off"){
        this.enemyCount+=this.e.dt;
      }

      if(this.enemyCount>this.enemyLim){

        this.enemyCount=0;
        this.enemyBlink=0;
        // this.enemyLim=this.e.u.ran(5)+15;
        this.enemyLim=4;

        var pos=this.e.u.ran(3);
        if(pos===0){
          this.enemy.position.x=-190;
        }else if(pos===1){
          this.enemy.position.x=0;
        }else{
        // }else if(pos===2){
          this.enemy.position.x=190;
        }

        this.e.s.p("warning");
        this.enemyAction="blink";

      }

      // document.getElementById("percTextDiv").innerHTML = "DISTANCE " + (this.playerCont.position.y/this.gameHeight) +"%";

    }else if(this.enemyAction==="blink"){

      // this.enemyCont.position.y=-this.levCont.position.y-(window.innerHeight*.55);
      this.enemy.position.y=-this.levCont.position.y+100;

      this.enemyBlink+=this.e.dt;
      if(this.enemyBlink>.5){

        this.enemyBlink=0;

        if(this.enemy.alpha===1){
          this.enemy.alpha=0;
        }else{
          this.enemy.alpha=1;
          this.e.s.p("warning");
        }

      }

      this.enemyCount+=this.e.dt;
      if(this.enemyCount>3){

        this.enemy.alpha=1;
        this.enemyCount=0;
        this.enemyAction="down";

      }

    }else if(this.enemyAction==="down"){
      
      this.enemyCount+=this.e.dt;
      if(this.enemyCount>5){

        this.enemyCount=0;
        this.enemyAction="wait";

      }

      if(this.e.u.hitTest(this.player, this.enemy)===true){

        this.e.s.p("enemyHit")
        
        this.hitPenalty();

        // this.hits+=1;
        // this.score-=50;

        this.bonusScore=0;
        this.life-=10*this.penaltyMult;
        if(this.upperRightText) {
          this.upperRightText.innerHTML = "LIFE: " + Math.round(this.life);
          this.upperRightText.style.opacity = "1";
        }

        for(var i=0; i<30; i++){
          this.setParticle(this.playerCont.position.x, this.playerCont.position.y)
        }
        
        this.enemyAction="hit";
  
      }
  
    }else if(this.enemyAction==="hit"){

      if(this.action==="game"){

        this.hitBlink+=this.e.dt;
        if(this.hitBlink>.06){
  
          if(this.playerCont.alpha===1){
            this.playerCont.alpha=0;
          }else{
            this.playerCont.alpha=1;
          }
  
          this.hitBlink=0;
        }
        
        this.enemyCount+=this.e.dt;
        if(this.enemyCount>4){
  
          this.playerCont.alpha=1;
          this.enemyCount=0;
          this.enemyAction="wait";
  
        }
  
      }

    }else if(this.enemyAction==="off"){

      this.enemy.alpha=0;

    }

  }

