  particles(){

    if(this.particlesVar===undefined){

      this.partArray=[];

      for(var i=0; i<100; i++){

        this.part = new pixi_js__WEBPACK_IMPORTED_MODULE_1__.Sprite(this.e.ui.coinRed);
        this.part.anchor.x = 0.5;
        this.part.anchor.y = 0.5;
        this.part.position.x = 10000;
        this.part.position.y = 10000;
        this.part._zIndex = 20;
        this.levCont.addChild(this.part);

        this.part.action="ready";
    
        this.partArray.push(this.part);

      }

      this.partCount = 0;

      this.particlesVar=true;

    }

    if(this.makeParticles===true && this.onWall===false && this.action==="game"){

      this.partCount+=this.e.dt;
      if(this.partCount>.02){

        for(var i=0; i<this.partArray.length; i++){

          var p = this.partArray[i];

          if(p.action==="ready"){

            p.position.x=this.playerCont.position.x;
            p.position.y=this.playerCont.position.y;
            p.scale.x = p.scale.y = (this.e.u.ran(40)+40)/100;
            // p.scale.x = p.scale.y = .8;
            p.xspeed=this.e.u.nran(50);
            p.yspeed=this.e.u.nran(50);
            p.rotSpeed=this.e.u.nran(10);
  
            if(this.playerColor==="b"){
              p.texture=this.e.ui.playerBlue;
            }else{
              p.texture=this.e.ui.playerRed;
            }
  
            p.action="go"
            this.partCount=0;
  
            i=1000;
  
          }

        }

      }

    }

    //--------

    for(var i=0; i<this.partArray.length; i++){

      var p = this.partArray[i];

      if(p.action==="ready"){

        p.position.x = 10000;
        p.position.y = 10000;

      }else if(p.action==="go"){

        p.rotation+=p.rotSpeed*this.e.dt;

        p.scale.x*=.96;
        p.scale.y*=.96;

        p.position.x+=p.xspeed*this.e.dt;
        p.position.y+=p.yspeed*this.e.dt;

        p.alpha=p.scale.x*.6;

        if(p.alpha<.04){
          p.action="ready"
        }

      }

    }

  }

