  rgbToHex(red, green, blue) {
    
    red = Math.min(255, Math.max(0, red));
    green = Math.min(255, Math.max(0, green));
    blue = Math.min(255, Math.max(0, blue));

    // Convert the RGB values to a single hexadecimal value
    const hexValue = (red << 16) | (green << 8) | blue;

    // Format the hexadecimal value in the desired format
    const formattedHex = "0x" + hexValue.toString(16).toUpperCase().padStart(6, '0');

    return formattedHex;

  }

  hexToRgb(hexValue) {

    // console.log("hv "+hexValue)

    //convert to string if not
    hexValue = hexValue.toString();

    // Remove the "0x" prefix if present
    if (hexValue.startsWith('0x')) {
      hexValue = hexValue.slice(2);
    }

    // console.log("hv2 "+hexValue)

    // Parse the hexadecimal value to an integer
    const intValue = parseInt(hexValue, 16);

    // Extract the red, green, and blue components using bitwise operations
    const red = (intValue >> 16) & 255;
    const green = (intValue >> 8) & 255;
    const blue = intValue & 255;

    return { red, green, blue };

  }

